INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Wartung
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Wartung eines IT-Systems immer erforderlich, um dessen Funktionalität zu gewährleisten?', 2, '[{"text": "Ja", "correct": true, "because": "Regelmäßige Wartung verhindert Ausfälle"}, {"text": "Nein", "correct": false, "because": "Ohne Wartung drohen Probleme"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine gut geplante Wartung die Lebensdauer von Hardware verlängern?', 2, '[{"text": "Ja", "correct": true, "because": "Pflege reduziert Verschleiß"}, {"text": "Nein", "correct": false, "because": "Wartung wirkt sich positiv aus"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Wartungsarbeiten immer während des laufenden Betriebs durchgeführt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Planung erlaubt Stillstände"}, {"text": "Ja", "correct": false, "because": "Wartung kann außerhalb des Betriebs erfolgen"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Schulungen für Mitarbeiter die Effektivität der Wartung erhöhen?', 2, '[{"text": "Ja", "correct": true, "because": "Wissen verbessert Ausführung"}, {"text": "Nein", "correct": false, "because": "Schulungen sind nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist präventive Wartung ausschließlich auf Hardware beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software erfordert Prävention"}, {"text": "Ja", "correct": false, "because": "Wartung umfasst beide Bereiche"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme gehört typischerweise zur präventiven Wartung?', 3, '[{"text": "Regelmäßige Updates", "correct": true, "because": "Verhindert Sicherheitslücken"}, {"text": "Reaktion auf Ausfälle", "correct": false, "because": "Das ist reaktiv"}, {"text": "Installation neuer Hardware", "correct": false, "because": "Kein Wartungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die Wartung eines IT-Systems?', 2, '[{"text": "Sicherstellung der Verfügbarkeit", "correct": true, "because": "Minimiert Ausfallzeiten"}, {"text": "Erhöhung der Anschaffungskosten", "correct": false, "because": "Nicht gewünscht"}, {"text": "Reduktion der Benutzerzahl", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wird oft für die Planung von Wartungsarbeiten verwendet?', 2, '[{"text": "Wartungsmanagement-Software", "correct": true, "because": "Organisiert Abläufe"}, {"text": "Texteditor", "correct": false, "because": "Keine Planungsfunktion"}, {"text": "Grafikprogramm", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann durch mangelnde Wartung entstehen?', 3, '[{"text": "Systemausfälle", "correct": true, "because": "Ohne Pflege häufen sich Probleme"}, {"text": "Schnellere Leistung", "correct": false, "because": "Unrealistisch"}, {"text": "Automatische Updates", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Schulungen bei der Wartung?', 2, '[{"text": "Verbesserung der Kompetenz", "correct": true, "because": "Mitarbeiter lernen Wartungstechniken"}, {"text": "Erhöhung der Kosten", "correct": false, "because": "Nebenaspekt"}, {"text": "Vermeidung von Wartung", "correct": false, "because": "Gegenteil ist Ziel"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben gehören zur Wartung eines IT-Systems?', 4, '[{"text": "Software-Updates", "correct": true, "because": "Hält System aktuell"}, {"text": "Hardware-Reinigung", "correct": true, "because": "Verhindert Defekte"}, {"text": "Überprüfung von Logs", "correct": true, "because": "Erkennt Probleme"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine regelmäßige Wartung?', 3, '[{"text": "Geringere Ausfallzeiten", "correct": true, "because": "Probleme werden vorgebeugt"}, {"text": "Höhere Systemstabilität", "correct": true, "because": "Pflege optimiert"}, {"text": "Verbesserte Sicherheit", "correct": true, "because": "Updates schließen Lücken"}, {"text": "Schnellere Installation", "correct": false, "because": "Nicht direkt relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können durch fehlende Wartung entstehen?', 4, '[{"text": "Sicherheitslücken", "correct": true, "because": "Updates fehlen"}, {"text": "Hardwareausfälle", "correct": true, "because": "Keine Pflege"}, {"text": "Performanceverlust", "correct": true, "because": "System verschlechtert sich"}, {"text": "Geringere Benutzerfreundlichkeit", "correct": false, "because": "Indirekt betroffen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden gehören zur präventiven Wartung?', 3, '[{"text": "Regelmäßige Backups", "correct": true, "because": "Schützt Daten"}, {"text": "Monitoring", "correct": true, "because": "Erkennt Probleme früh"}, {"text": "Firmware-Updates", "correct": true, "because": "Hält Geräte aktuell"}, {"text": "Reaktion auf Beschwerden", "correct": false, "because": "Reaktiv, nicht präventiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ressourcen sind für eine effektive Wartung nötig?', 3, '[{"text": "Geschultes Personal", "correct": true, "because": "Kompetenz erforderlich"}, {"text": "Wartungspläne", "correct": true, "because": "Strukturieren Ablauf"}, {"text": "Tools und Software", "correct": true, "because": "Unterstützen Umsetzung"}, {"text": "Marketingmaterial", "correct": false, "because": "Irrelevant"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Wartung kann Systemausfälle verhindern. b) Wartung ist nur für Software notwendig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ausfälle ja, Hardware auch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Schulungen verbessern die Wartungsqualität. b) Präventive Wartung ist teurer als reaktive.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schulungen ja, Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Regelmäßige Updates sind Teil der Wartung. b) Wartung erfordert keine Planung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Updates ja, Planung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Präventive Wartung reduziert ungeplante Ausfälle. b) Wartung ist nur bei Hardwareausfällen nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prävention ja, Wartung umfassend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Wartung erhöht die Systemsicherheit. b) Geschultes Personal ist für Wartung irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit ja, Personal wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

